def apply_i18n(d):
    for L in ('es', 'ko', 'ja', 'zh'):
        p = os.path.join(d, L + '.json')
        if not os.path.exists(p):
            print('  i18n: skip (missing) ' + p); continue
        j = json.loads(open(p, encoding='utf-8').read())
        have_p = {k for k, _ in j.get('p', [])}
        add = 0
        for k, tr in I18N['p']:
            if k not in have_p:
                j.setdefault('p', []).append([k, tr[L]]); add += 1
        for k, tr in I18N['x']:
            if k not in j.setdefault('x', {}):
                j['x'][k] = tr[L]; add += 1
        with open(p, 'w', encoding='utf-8', newline='\n') as f:
            json.dump(j, f, ensure_ascii=False, separators=(',', ':'))
        print('  i18n: %s +%d' % (p, add))


def main():
    args = sys.argv[1:]
    if not args:
        print(__doc__); sys.exit(2)
    path = args[0]
    src = open(path, encoding='utf-8').read()
    for name, old, new in EDITS:
        n = src.count(old)
        assert n == 1, 'S anchor count %d (need 1): %s' % (n, name)
    for name, old, new in EDITS:
        assert src.count(old) == 1, 'S anchor became ambiguous while applying: ' + name
        src = src.replace(old, new, 1)
        print('  ' + name)
    with open(path, 'w', encoding='utf-8', newline='') as f:
        f.write(src)
    print('S_patch: %d edits applied to %s' % (len(EDITS), path))
    if '--i18n' in args:
        apply_i18n(args[args.index('--i18n') + 1])


if __name__ == '__main__':
    main()
